export default function Section({ id, title, content, projects }) {
  return (
    <section id={id} className="section py-16 px-6 bg-gray-900 text-white">
      <h2 className="text-4xl font-bold mb-10 text-center">{title}</h2>

      {projects ? (
        <div className="projects grid sm:grid-cols-2 gap-8 max-w-5xl mx-auto">
          {projects.map((p, i) => (
            <div
              key={i}
              className="project-card bg-gray-800 rounded-2xl shadow-lg hover:shadow-xl transition-transform transform hover:-translate-y-1 p-6"
            >
              {/* Optional project image */}
              {p.image && (
                <img
                  src={p.image}
                  alt={p.name}
                  className="rounded-lg mb-4 w-full h-48 object-cover"
                />
              )}

              <h3 className="text-2xl font-semibold mb-2">{p.name}</h3>
              <p className="text-gray-300 mb-4 leading-relaxed">{p.desc}</p>

              <a
                href={p.link}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg font-medium transition"
              >
                View Project →
              </a>
            </div>
          ))}
        </div>
      ) : (
        <div className="section-content max-w-3xl mx-auto">{content}</div>
      )}
    </section>
  );
}

